window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3488200e682acafc"]={"versions": [{"id": "FIG-3488200e682acafc", "releases": ["R1.3.0", "R1.5.1", "R17-03_R1.1.0", "R17-10_R1.2.0", "R18-03_R1.4.0", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll- und Paketstrukturdiagramm für das AUTOSAR Log and Trace Protocol (DLT). Es stellt den schematischen Aufbau einer Nachricht im Verbose Mode auf Bitebene bzw. Feldebene dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Nachricht gliedert sich horizontal in aufeinanderfolgende Protokollabschnitte:</p>\n<ul class=\"fig-list\">\n<li>Standard Header: Feste Protokollkopfdaten zu Beginn der Nachricht (orange hinterlegt).</li>\n<li>Extended Header: Erweiterter Protokollkopf (blau hinterlegt).</li>\n<li>Payload: Nutzlastbereich (hellgrün hinterlegt), hierarchisch unterteilt in mehrere Argumente:</li>\n<li>Argument 1 bis Argument n: Einzelne Datenargumente.</li>\n<li>Jedes Argument besteht aus zwei Teilfeldern: Type Info (Metadaten/Typinformation) und Data Payload (eigentliche Nutzdaten).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenformat ohne Sequenzabläufe. Die Nachricht wird sequenziell von links nach rechts serialisiert und übertragen: Zunächst der Standard Header, gefolgt vom Extended Header und der Payload. Innerhalb der Payload folgen die Argumente 1 bis n fortlaufend, jeweils mit vorangestelltem Type Info und anschließendem Data Payload.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert das normative Frame-Layout für DLT-Nachrichten im Verbose Mode. Im Verbose Mode ist jedem Nutzdatenargument zwingend ein eigenes Type-Info-Feld vorangestellt, das die Interpretation des nachfolgenden Data-Payload-Werts zur Laufzeit ermöglicht. Die Aufteilung in Standard Header, Extended Header und strukturierte Payload-Elemente ist bei der Implementierung von DLT-Parsern und -Serialisierern strikt einzuhalten.</p>"}, {"id": "FIG-21e2507241fface0", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll- und Paketstrukturdiagramm für das AUTOSAR Log and Trace Protocol (DLT). Es stellt den schematischen Aufbau einer Nachricht im Verbose Mode auf Bitebene bzw. Feldebene dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Nachricht gliedert sich horizontal in aufeinanderfolgende Protokollabschnitte:</p>\n<ul class=\"fig-list\">\n<li>Base Header: Grundlegende Protokollkopfdaten zu Beginn der Nachricht (orange hinterlegt).</li>\n<li>(opt.) Extension Header: Optionaler Erweiterungs-Header (blau hinterlegt).</li>\n<li>Payload: Nutzlastbereich (hellgrün hinterlegt), hierarchisch unterteilt in mehrere Argumente:</li>\n<li>Argument 1 bis Argument n: Einzelne Datenargumente.</li>\n<li>Jedes Argument besteht aus zwei Teilfeldern: Type Info (Metadaten/Typinformation) und Data Payload (eigentliche Nutzdaten).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenformat ohne Sequenzabläufe. Die Nachricht wird sequenziell von links nach rechts serialisiert und übertragen: Zunächst der Base Header, gefolgt von dem optionalen Extension Header und der Payload. Innerhalb der Payload folgen die Argumente 1 bis n fortlaufend, jeweils mit vorangestelltem Type Info und anschließendem Data Payload.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert das normative Frame-Layout für DLT-Nachrichten im Verbose Mode. Im Verbose Mode ist jedem Nutzdatenargument zwingend ein eigenes Type-Info-Feld vorangestellt, das die Interpretation des nachfolgenden Data-Payload-Werts zur Laufzeit ermöglicht. Die Kennzeichnung als „(opt.) Extension Header“ weist auf das optionale Vorhandensein des Erweiterungs-Headers nach dem Base Header hin. Die Feldabfolge ist bei der Implementierung von DLT-Parsern und -Serialisierern strikt einzuhalten.</p>"}, {"id": "FIG-612573776ac2883d", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll- und Paketstrukturdiagramm für das AUTOSAR Log and Trace Protocol (DLT). Es stellt den schematischen Aufbau einer Nachricht im Verbose Mode auf Bitebene bzw. Feldebene dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Nachricht gliedert sich horizontal in aufeinanderfolgende Protokollabschnitte:</p>\n<ul class=\"fig-list\">\n<li>Base Header: Grundlegende Protokollkopfdaten zu Beginn der Nachricht (orange hinterlegt).</li>\n<li>(opt.) Extension Header: Optionaler Erweiterungs-Header (blau hinterlegt).</li>\n<li>Payload: Nutzlastbereich (hellgrün hinterlegt), hierarchisch unterteilt in mehrere Argumente:</li>\n<li>Argument 1 bis Argument n: Einzelne Datenargumente.</li>\n<li>Jedes Argument besteht aus zwei Teilfeldern: Type Info (Metadaten/Typinformation) und Data Payload (eigentliche Nutzdaten).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenformat ohne Sequenzabläufe. Die Nachricht wird sequenziell von links nach rechts serialisiert und übertragen: Zunächst der Base Header, gefolgt von dem optionalen Extension Header und der Payload. Innerhalb der Payload folgen die Argumente 1 bis n fortlaufend, jeweils mit vorangestelltem Type Info und anschließendem Data Payload.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert das normative Frame-Layout für DLT-Nachrichten im Verbose Mode. Im Verbose Mode ist jedem Nutzdatenargument zwingend ein eigenes Type-Info-Feld vorangestellt, das die Interpretation des nachfolgenden Data-Payload-Werts zur Laufzeit ermöglicht. Die Kennzeichnung als „(opt.) Extension Header“ weist auf das optionale Vorhandensein des Erweiterungs-Headers nach dem Base Header hin. Die Feldabfolge ist bei der Implementierung von DLT-Parsern und -Serialisierern strikt einzuhalten.</p>"}], "trans": [{"from": "FIG-3488200e682acafc", "to": "FIG-21e2507241fface0", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Header-Segmente umbenannt: „Standard Header“ in „Base Header“, „Extended Header“ in „(opt.) Extension Header“.</li>\n</ul>"}, {"from": "FIG-21e2507241fface0", "to": "FIG-612573776ac2883d", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
